          m.screen=[px,py];m.depth=depth;m.facing=facing;m.visible=visible;
          const op=m.side&&!m.always?Math.max(0,Math.min(1,(facing-.15)/.35)):1;m.opacity=visible?op:0;
          b.style.transform='translate3d('+px.toFixed(1)+'px,'+py.toFixed(1)+'px,0)';b.style.visibility=visible?'visible':'hidden';b.style.opacity=String(m.opacity);
