// Test "Bay coat": the Studio look painted with the bay coat of the reference photo. Derived from Direction A, "Studio": graphite satin horse, studio key light, cool rim lights, glossy floor reflection,
// the zones glow on the body itself. Normal points stay as small quiet pins.
(function(){
  'use strict';
  const LOOK = {
    name:'bay', aspect:'1/0.86', background:'#14181F',
    camera:{fov:15,pitch:7,fit:[1.93,1.63],target:[0,1.16,0]},
    idle:{rest:.12,amp:.2,period:18},
    /* points like the reference photo: a small solid dot, a thin leader line and a quiet label pill, pointing away from the body */
    css:
      /* style A « Anneau fin » (chosen 1 Oct): a thin ring with a tiny core; the points to watch get a coloured ring */
      /* points on the bay coat: a small solid dot in its colour with a thin white edge, readable without being heavy */
      '.h3d-bay .mk .pin{position:relative;display:block;width:9px;height:9px;border-radius:50%;background:var(--c);border:1.5px solid rgba(255,255,255,.92);box-sizing:content-box;box-shadow:0 1px 4px rgba(0,0,0,.45);transition:transform .3s cubic-bezier(.32,.72,0,1)}'
      +'.h3d-bay .mk:not([data-state=normal]) .pin{width:11px;height:11px;box-shadow:0 1px 4px rgba(0,0,0,.45),0 0 0 4px color-mix(in srgb,var(--c) 30%,transparent),0 0 14px 2px color-mix(in srgb,var(--c) 55%,transparent)}'
      +'.h3d-bay .mk[aria-pressed=true] .pin{transform:scale(1.3)}'
      +'.h3d-bay .mk .tag{position:absolute;top:50%;left:calc(50% + 22px);transform:translate(4px,-50%);white-space:nowrap;padding:5px 10px;border-radius:999px;background:rgba(24,28,36,.86);border:1px solid rgba(255,255,255,.08);'
      +'font:500 11.5px/1.15 -apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif;letter-spacing:.1px;color:#D9DEE6;opacity:0;pointer-events:none;transition:opacity .3s,transform .35s cubic-bezier(.32,.72,0,1);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}'
      +'.h3d-bay .mk .tag::before{content:"";position:absolute;top:50%;right:100%;width:16px;height:1px;background:rgba(255,255,255,.3)}'
      +'.h3d-bay .mk[data-dir=l] .tag{left:auto;right:calc(50% + 22px);transform:translate(-4px,-50%)}'
      +'.h3d-bay .mk[data-dir=l] .tag::before{right:auto;left:100%}'+'.h3d-bay .mk[data-dir=t] .tag{left:50%;top:auto;bottom:calc(50% + 14px);transform:translate(-50%,-4px)}.h3d-bay .mk[data-dir=t] .tag::before{display:none}'
      +'.h3d-bay .mk[aria-pressed=true] .tag{opacity:1;transform:translate(0,-50%)}'+'.h3d-bay .mk[data-dir=t][aria-pressed=true] .tag{transform:translate(-50%,0)}'
      +'.h3d-bay .mk .tag i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--c);margin-right:7px;vertical-align:1px}',
    markerHTML(m){return '<span class="pin"></span><span class="tag"><i></i>'+m.p.name+'</span>';},
    /* the label goes away from the body, and flips (or sits above) when it would leave the picture */
    frame(S,F){ for(const m of F.markers){ if(!m.screen||!m.button) continue; const b=m.button, w=b.parentNode.clientWidth||1, x=m.screen[0];
      const t=b.querySelector('.tag'), tw=(t&&t.offsetWidth)||90, room=22+tw+8;
      let d=x<w*.5?'l':'r'; if(d==='l'&&x-room<0) d=x+room<=w?'r':'t'; else if(d==='r'&&x+room>w) d=x-room>=0?'l':'t';
      if(b.dataset.dir!==d) b.dataset.dir=d; } },
    setup(S){
      const {gl,SHADER}=S;
      S.progs.bg=S.program('attribute vec2 a;varying vec2 uv;void main(){uv=a*.5+.5;gl_Position=vec4(a,0.,1.);}',
        'precision mediump float;varying vec2 uv;uniform vec2 size;uniform float horizon;'+SHADER.DITHER
        +'void main(){vec2 p=uv;float asp=size.x/size.y;'
        +'vec3 base=vec3(20.,24.,31.)/255.;'
        // soft key spot behind the horse, cooler towards the corners
        +'vec2 d=(p-vec2(.47,.62))*vec2(asp,1.);float spot=exp(-dot(d,d)*2.1);'
        +'vec3 c=base+vec3(.062,.072,.094)*spot;'
        // floor: a slightly lighter band that fades towards the viewer
        +'float f=smoothstep(horizon+.004,horizon-.08,p.y);vec2 fd=(p-vec2(.5,horizon-.05))*vec2(asp*.55,2.4);c+=vec3(.022,.026,.034)*f*exp(-dot(fd,fd));'
        +'float e=min(min(p.x,1.-p.x),min(p.y,1.-p.y));c=mix(base,c,smoothstep(0.,.22,e));'
        +'gl_FragColor=vec4(c+dither(gl_FragCoord.xy)/255.,1.);}',['a'],['size','horizon']);
      S.progs.shadow=S.program('attribute vec2 a;uniform vec2 rot;uniform mat4 vp;varying vec2 o;void main(){o=a*vec2(2.6,1.3);vec3 w=vec3(rot.x*o.x+rot.y*o.y,.002,-rot.y*o.x+rot.x*o.y);gl_Position=vp*vec4(w,1.);}',
        'precision mediump float;varying vec2 o;uniform vec4 hA;uniform vec4 hB;'+SHADER.DITHER
        +'float g(vec2 p,vec2 c,vec2 r){vec2 d=(p-c)/r;return exp(-dot(d,d));}'
        +'void main(){float body=g(o,vec2(.5,0.),vec2(1.45,.42));float h=g(o,hA.xy,vec2(.13))+g(o,hA.zw,vec2(.13))+g(o,hB.xy,vec2(.13))+g(o,hB.zw,vec2(.13));'
        +'float a=clamp(body*.55+h*.55,0.,.85);gl_FragColor=vec4(vec3(.004,.005,.007),a+dither(gl_FragCoord.xy)/255.);}',['a'],['rot','vp','hA','hB']);
      S.progs.horse=S.program(SHADER.HORSE_VS,
        'precision highp float;varying vec3 vw;varying vec3 vn;varying vec3 vo;varying float vao;varying vec3 vcol;uniform vec3 eye;uniform vec3 kpPos[12];uniform vec4 kpCol[12];uniform float refl;'+SHADER.DITHER+SHADER.TONE
        +'void main(){vec3 N=normalize(vn);vec3 V=normalize(eye-vw);float ndv=clamp(dot(N,V),0.,1.);float ao=smoothstep(.05,.82,vao);'
        +'vec3 alb=pow(vcol*vec3(.95,.9,.9),vec3(2.2))*.5;'
        +'vec3 Lk=normalize(vec3(-.42,.86,.55));float wrap=max((dot(N,Lk)+.12)/1.12,0.);'
        +'vec3 c=alb*(vec3(1.95,1.9,1.82)*wrap*mix(.25,1.,ao)+vec3(.11,.13,.17)*(.55+.45*N.y)*ao);'
        +'vec3 H=normalize(Lk+V);float nh=max(dot(N,H),0.);c+=vec3(1.,.98,.96)*(pow(nh,8.)*.018+pow(nh,30.)*.045)*ao;'
        +'vec3 R=reflect(-V,N);float fr=.04+.96*pow(1.-ndv,5.);c+=vec3(.85,.9,1.)*smoothstep(.45,.95,R.y)*fr*.04*ao;'
        +'vec3 L1=normalize(vec3(-.75,.32,-.58));vec3 L2=normalize(vec3(.8,.42,-.45));float edge=pow(1.-ndv,2.2);'
        +'c+=vec3(.55,.68,.95)*edge*(max(dot(N,L1),0.)*.42+max(dot(N,L2),0.)*.36+.02)*mix(.45,1.,ao);'
        +'vec3 q=vec3(vo.xy,abs(vo.z));vec3 heat=vec3(0.);'
        +'for(int i=0;i<12;i++){float r=kpCol[i].a;if(r<=0.)continue;float dd=length(q-kpPos[i])/r;'
        +'heat+=kpCol[i].rgb*(exp(-dd*dd*1.9)*1.55+exp(-dd*dd*.6)*.18);}'
        +'c+=heat*(.4+.6*ndv)*.32;'
        +'c=tone(c*1.18);c=pow(c,vec3(1./2.2));'
        +'if(refl>.5){float fade=exp(vw.y*3.2)*.16;gl_FragColor=vec4(c,fade);}else gl_FragColor=vec4(c+dither(gl_FragCoord.xy)/255.,1.);}',
        ['p','n','ao','col'],['rot','vp','flip','eye','kpPos','kpCol','refl']);
      const sh=S.progs.shadow,hv=S.geo.hooves;gl.useProgram(sh.p);gl.uniform4f(sh.hA,hv[0][0],hv[0][1],hv[1][0],hv[1][1]);gl.uniform4f(sh.hB,hv[2][0],hv[2][1],hv[3][0],hv[3][1]);
      const pos=[];for(const p of S.points)pos.push(...S.geo.anchors[p.id][1]);gl.useProgram(S.progs.horse.p);gl.uniform3fv(S.progs.horse.kpPos,pos);
    },
    animating(S){return S.points.some(p=>p.state==='attention');},
    draw(S,F){
      const {gl}=S,h=S.progs.horse;
      // heat uniforms: watch and attention glow, attention breathes slowly, the selected zone is brighter
      const col=[];for(const p of S.points){const lin=S.hexLinear(S.PALETTE[p.state]);let k=p.state==='attention'?.95:p.state==='watch'?.6:0;
        if(F.selected===p.id)k=k?k*1.45:.38;
        const breathe=p.state==='attention'?1+.10*Math.sin(F.time*2.1):1;col.push(lin[0]*k*breathe,lin[1]*k*breathe,lin[2]*k*breathe,k?p.zone*(p.state==='attention'?breathe:1):0);}
      gl.clearColor(20/255,24/255,31/255,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
      gl.disable(gl.DEPTH_TEST);gl.disable(gl.BLEND);S.bindQuad('tri');
      // horizon in screen space: project the floor line far behind the horse
      const m=F.viewProj,cw=m[3]*0+m[7]*0+m[11]*-4+m[15],hy=(m[1]*0+m[5]*0+m[9]*-4+m[13])/cw*.5+.5;
      gl.useProgram(S.progs.bg.p);gl.uniform2f(S.progs.bg.size,F.width,F.height);gl.uniform1f(S.progs.bg.horizon,hy);gl.drawArrays(gl.TRIANGLES,0,3);
      // reflection on the floor
      gl.enable(gl.DEPTH_TEST);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
      S.bindHorse();gl.useProgram(h.p);gl.uniform2f(h.rot,F.c,F.s);gl.uniformMatrix4fv(h.vp,false,F.viewProj);gl.uniform3fv(h.eye,F.eye);gl.uniform4fv(h.kpCol,col);
      gl.enable(gl.CULL_FACE);gl.cullFace(gl.FRONT);gl.uniform1f(h.flip,-1);gl.uniform1f(h.refl,1);S.drawHorse();gl.disable(gl.CULL_FACE);
      gl.clear(gl.DEPTH_BUFFER_BIT);gl.disable(gl.DEPTH_TEST);
      S.bindQuad('quad');gl.useProgram(S.progs.shadow.p);gl.uniform2f(S.progs.shadow.rot,F.c,F.s);gl.uniformMatrix4fv(S.progs.shadow.vp,false,F.viewProj);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
      gl.disable(gl.BLEND);gl.enable(gl.DEPTH_TEST);
      S.bindHorse();gl.useProgram(h.p);gl.enable(gl.CULL_FACE);gl.cullFace(gl.BACK);gl.uniform1f(h.flip,1);gl.uniform1f(h.refl,0);S.drawHorse();gl.disable(gl.CULL_FACE);
    }
  };
  window.SD_LOOK_BAY=function(container,options){return HorseStage(container,options,LOOK);};
})();


/* the app: the bay horse only (Louis, 1 Oct). The other renderings stay in heatmap-propositions/. */
window.initHorse3D=function(container,options){ return window.SD_LOOK_BAY(container,options); };
